import json
from pathlib import Path

import pandas as pd


SOURCES = [
    ("source_a", Path("/data/source_a/users.json")),
    ("source_b", Path("/data/source_b/users.csv")),
    ("source_c", Path("/data/source_c/users.parquet")),
]

FIELD_ALIASES = {
    "user_id": ["user_id", "id", "userId"],
    "email": ["email", "email_address"],
    "name": ["full_name", "name", "userName"],
    "created_date": ["registration_date", "created_at", "joined"],
    "status": ["status", "is_active", "active"],
}

OUTPUT_FIELDS = ["user_id", "name", "email", "created_date", "status"]


def load_source(path):
    suffix = path.suffix.lower()
    if suffix == ".json":
        with path.open() as f:
            return pd.DataFrame(json.load(f))
    if suffix == ".csv":
        return pd.read_csv(path)
    if suffix == ".parquet":
        return pd.read_parquet(path)
    raise ValueError(f"Unsupported source format: {path}")


def normalize_status(value):
    if isinstance(value, bool):
        return "active" if value else "inactive"
    if value is None:
        return None
    text = str(value).strip().lower()
    if text in {"true", "1", "yes", "y", "active"}:
        return "active"
    if text in {"false", "0", "no", "n", "inactive"}:
        return "inactive"
    return str(value).strip()


def normalize_date(value):
    if value is None:
        return None
    if pd.isna(value):
        return None
    parsed = pd.to_datetime(value, errors="coerce")
    if pd.isna(parsed):
        return str(value)
    return parsed.strftime("%Y-%m-%d")


def normalize_field(field, value):
    if value is None or (not isinstance(value, (list, dict)) and pd.isna(value)):
        return None
    if field == "user_id":
        return int(value)
    if field == "created_date":
        return normalize_date(value)
    if field == "status":
        return normalize_status(value)
    return str(value).strip()


def extract_records(name, df):
    records = {}
    for _, row in df.iterrows():
        raw_id = None
        for alias in FIELD_ALIASES["user_id"]:
            if alias in df.columns and pd.notna(row[alias]):
                raw_id = row[alias]
                break
        if raw_id is None:
            continue

        user_id = normalize_field("user_id", raw_id)
        record = {}
        for field, aliases in FIELD_ALIASES.items():
            if field == "user_id":
                continue
            value = None
            for alias in aliases:
                if alias in df.columns and pd.notna(row[alias]):
                    value = normalize_field(field, row[alias])
                    break
            if value is not None:
                record[field] = value
        records[user_id] = record
    return records


def main():
    source_records = {}
    for name, path in SOURCES:
        source_records[name] = extract_records(name, load_source(path))

    source_names = [name for name, _ in SOURCES]
    all_user_ids = sorted(
        {user_id for records in source_records.values() for user_id in records}
    )

    merged_rows = []
    conflicts = []

    for user_id in all_user_ids:
        row = {"user_id": user_id}
        for field in OUTPUT_FIELDS:
            if field == "user_id":
                continue

            values = {}
            for source in source_names:
                record = source_records[source].get(user_id)
                if record and field in record:
                    values[source] = record[field]

            if not values:
                row[field] = None
                continue

            selected = next(values[source] for source in source_names if source in values)
            row[field] = selected

            distinct = {str(v) for v in values.values()}
            if len(distinct) > 1:
                conflicts.append(
                    {
                        "user_id": user_id,
                        "field": field,
                        "values": values,
                        "selected": selected,
                    }
                )
        merged_rows.append(row)

    columns = OUTPUT_FIELDS
    merged = pd.DataFrame(merged_rows, columns=columns)
    merged["user_id"] = merged["user_id"].astype("int64")
    for column in ["name", "email", "created_date", "status"]:
        merged[column] = merged[column].astype("string")

    merged.to_parquet("/app/merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w") as f:
        json.dump(report, f, indent=2)

    print(merged.to_string(index=False))
    print(f"\nTotal conflicts: {len(conflicts)}")


if __name__ == "__main__":
    main()
